  if (total === 0) return;
  const target = Math.max(0, Math.min(total - 1, Math.floor(Number(next) || 0)));
  // Each sheet has its own region: a shared `vv` belongs to the sheet it was
  // copied from, so switching sheets starts on the whole sheet.
