function loadSheetThumb(button) {
  if (!button || button.querySelector('img')) return;
  const url = button.dataset.thumb;
  if (!url) return;
  button.prepend(
    el('img', {
      src: url,
      alt: '',
      loading: 'lazy',
      decoding: 'async',
      onerror: (event) => {
        event.currentTarget.hidden = true;
