// Sweep: open the detail panel for a sample of records and look for defects.
import { launch, sleep } from '/tmp/cdp.mjs';

const BASE = 'http://127.0.0.1:8787';
const ids = process.argv.slice(2);
const d = await launch({ port: 9777, width: 1280, height: 950 });
const rows = [];
for (const id of ids) {
  d.logs.length = 0;
  await d.goto(`${BASE}/?sel=${encodeURIComponent(id)}`, 2500);
  let state = 'none';
  for (let i = 0; i < 30; i += 1) {
    state = await d.eval(`document.querySelector('#viewer-stage')?.dataset.state ?? document.querySelector('#detail-preview')?.firstElementChild?.className ?? 'none'`);
    if (state === 'ready' || state === 'error' || String(state).includes('fallback')) break;
    await sleep(500);
  }
  const info = await d.eval(`(() => {
    const p = document.querySelector('#detail');
    const img = document.querySelector('#detail-preview img');
    const rd = document.querySelector('#viewer-readout');
    return {
      open: !p.hidden,
      title: (document.querySelector('#detail-title')?.textContent ?? '').slice(0, 46),
      state: document.querySelector('#viewer-stage')?.dataset.state ?? null,
      face: document.querySelector('#detail-preview')?.firstElementChild?.className,
      imgW: img?.naturalWidth ?? 0, imgH: img?.naturalHeight ?? 0,
      readout: rd?.textContent ?? null,
      readoutLive: rd?.getAttribute('aria-live') ?? null,
      sheets: document.querySelectorAll('#page-strip [data-sheet]').length,
      facts: document.querySelectorAll('#detail dl > *').length,
      text: (document.querySelector('#detail')?.innerText ?? '').replace(/\\s+/g, ' ').slice(0, 240),
      overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    };
  })()`);
  const errs = d.logs.filter((l) => l.type === 'error' || l.type === 'exception' || l.type === 'log:error').map((l) => l.text.slice(0, 120));
  rows.push({ id, info, errs });
  console.log(id, JSON.stringify(info));
  if (errs.length) console.log('   !!', JSON.stringify(errs));
}
console.log('\nsummary: ', rows.filter((r) => !r.info.open).length, 'not open,', rows.filter((r) => r.errs.length).length, 'with console errors');
await d.close();

