/* --- 8h4. a shared ?sel= link marks the same record in list and map --- */
// `selected` is one value in the store and the URL carries it. The result list
// restores its `aria-current` row from it since iteration 7-14; the map used to
// keep a private copy that only a click filled, so a shared link (or a reload
// of one) opened the panel while the map showed nothing as selected — the two
// coordinated views disagreed about the one thing the link is about.
await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
await cdp.send('Page.navigate', { url: `${BASE_URL}/` });
await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 20`, { label: 'rows for the shared-selection check' });
await cdp.waitFor(`document.querySelectorAll('.map-marker:not(.map-cluster)').length > 0`, { label: 'pins for the shared-selection check' });
await sleep(700);
// Only records inside the current viewport have a pin, so the link has to name
// one of them: the check is about the two views agreeing, not about a pin that
// the map legitimately cannot show.
const selectionId = await cdp.eval(`[...document.querySelectorAll('.map-marker:not(.map-cluster)')].map((node) => node.dataset.id).find(Boolean) ?? null`);
const readSelection = () =>
  cdp.eval(`(() => ({
    sel: new URLSearchParams(location.search).get('sel'),
    row: document.querySelector('#result-list [aria-current="true"]')?.dataset.recordId ?? null,
    pin: document.querySelector('.map-marker.is-selected')?.dataset.id ?? null,
    panelOpen: document.querySelector('#detail').hidden === false,
  }))()`);
let sharedSelection = null;
let afterEscape = null;
if (selectionId) {
  await cdp.send('Page.navigate', { url: `${BASE_URL}/?sel=${encodeURIComponent(selectionId)}` });
  await cdp.waitFor(`document.querySelector('#detail').hidden === false`, { label: 'panel for the shared-selection check' });
  await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 20`, { label: 'rows for the shared-selection check (reload)' });
  await sleep(900);
  sharedSelection = await readSelection();
  await cdp.pressKey('Escape');
  await sleep(400);
  afterEscape = await readSelection();
}
check(
  'a shared ?sel= link marks the record in the list, on the map and in the panel',
  Boolean(selectionId) && sharedSelection?.sel === selectionId && sharedSelection?.row === selectionId && sharedSelection?.pin === selectionId && sharedSelection?.panelOpen === true,
  `${selectionId} -> ${JSON.stringify(sharedSelection)}`,
);
// Closing the drawer is not a new selection: the URL still names the record, so
// the row and the pin stay marked (a reload of the same link reopens the panel)
// instead of three views telling three different stories.
check(
  'closing the panel keeps list, map and URL agreeing on the selected record',
  Boolean(selectionId) && afterEscape?.panelOpen === false && afterEscape?.sel === selectionId && afterEscape?.row === selectionId && afterEscape?.pin === selectionId,
  JSON.stringify(afterEscape),
);
await cdp.screenshot(path.join(OUT_DIR, '13b-shared-selection.png')).then(() => report.screenshots.push('13b-shared-selection.png'));

