ctx.bus.on('records:loaded', () => {
  const id = ctx.store.getState().selected;
  if (!id) return;
  const record = ctx.data.recordIndex.get(id);
  if (record) {
    if (panel.hidden) open(record, { keepSheet: true });
    return;
  }
  // A link that names a record the seed no longer holds (an older harvest, a
  // hand-written id): the panel cannot open, and a URL that claims a selection
  // the app does not show is worse than no link at all. The value is dropped
  // with `replace` — clearing it is not a step the visitor took — and the
  // console keeps the id for whoever debugs the link. The list and the map
  // follow through the same store key they always read.
  console.info(`[kartenzeit] der verlinkte Datensatz „${id}“ ist nicht im Bestand – die Auswahl wird aus dem Link entfernt.`);
  ctx.store.update({ selected: '' }, { history: 'replace' });
});

