  // console keeps the id for whoever debugs the link. The list and the map
  // follow through the same store key they always read.
  console.info(`[kartenzeit] der verlinkte Datensatz „${id}“ ist nicht im Bestand – die Auswahl wird aus dem Link entfernt.`);
  ctx.store.update({ selected: '' }, { history: 'replace' });
